package com.fitbite.recommendation;
import com.fitbite.dto.RecommendationDtos.*; import com.fitbite.dto.RecipeDtos.*; import com.fitbite.entity.*; import com.fitbite.repository.*; import com.fitbite.service.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.*;
@Service public class RecommendationService { private final RecipeRepository recipes; private final RecommendationRepository saved; private final CurrentUserService current; private final RecipeService recipeService; public RecommendationService(RecipeRepository recipes,RecommendationRepository saved,CurrentUserService current,RecipeService recipeService){this.recipes=recipes;this.saved=saved;this.current=current;this.recipeService=recipeService;}
 @Transactional public List<ScoredRecipe> personalized(){User u=current.get();var p=u.getPreferences();List<Recipe> all=recipes.findAll();Set<Recipe> fav=u.getFavorites();return all.stream().map(r->{double s=0;List<String> reasons=new ArrayList<>();if(p!=null&&p.getHealthGoal()!=null&&r.getHealthGoals().stream().anyMatch(g->g.getName().equalsIgnoreCase(p.getHealthGoal()))){s+=35;reasons.add("matches your health goal");}if(p!=null&&p.getDietaryType()!=null&&contains(r.getDietaryTags(),p.getDietaryType())){s+=20;reasons.add("fits your dietary preference");}if(p!=null&&p.getMaxCalories()!=null&&r.getCalories()<=p.getMaxCalories()){s+=15;reasons.add("within your calorie target");}if(p!=null&&p.getMinProtein()!=null&&r.getProtein()>=p.getMinProtein()){s+=15;reasons.add("meets your protein target");}if(p!=null&&p.getMaxCookingTime()!=null&&r.getTotalTime()<=p.getMaxCookingTime()){s+=10;reasons.add("fits your cooking time");}if(fav.contains(r)){s+=5;reasons.add("similar to a favorite");}return new ScoredRecipe(RecipeMapper.summary(r,fav.contains(r)),s,reasons.isEmpty()?"good all-round match":String.join(", ",reasons));}).sorted(Comparator.comparingDouble(ScoredRecipe::score).reversed()).limit(12).toList();}
 public List<IngredientRecommendation> byIngredients(List<String> input){Set<String> have=input.stream().map(String::trim).filter(s->!s.isBlank()).map(String::toLowerCase).collect(Collectors.toSet());if(have.isEmpty())return List.of();return recipes.findAll().stream().map(r->{List<String> names=r.getIngredients().stream().map(x->x.getIngredient().getName().toLowerCase()).toList();long matched=names.stream().filter(have::contains).count();double pct=names.isEmpty()?0:matched*100.0/names.size();List<String> avail=names.stream().filter(have::contains).toList();List<String> miss=names.stream().filter(n->!have.contains(n)).toList();return new IngredientRecommendation(r.getId(),r.getName(),Math.round(pct*10)/10.0,avail,miss,r.getTotalTime(),r.getCalories(),r.getProtein());}).filter(x->x.matchPercentage()>=25).sorted(Comparator.comparingDouble(IngredientRecommendation::matchPercentage).reversed()).limit(12).toList();}
 private boolean contains(String tags,String v){return tags!=null&&tags.toLowerCase().contains(v.toLowerCase());}
}
